function Invoke-ProUpgradeStage($Session,$Meta,$Guard){
 $Guard.PinInputFile([string]$Meta.zip);if((Get-FileHash -LiteralPath $Meta.zip).Hash.ToLowerInvariant() -ne $Meta.zipSha256){throw 'Upgrade archive changed'}
 $archive='C:\MuLab\private\upgrade-'+$Meta.caseId+'-'+$Meta.revision+'.zip';Copy-Item -LiteralPath $Meta.zip -Destination $archive -ToSession $Session
 return Invoke-Command -Session $Session -ArgumentList $Meta,$archive -ScriptBlock {
  param($meta,$archive)
  $ErrorActionPreference='Stop';$file='C:\MuLab\approved\upgrade-'+$meta.caseId+'-config.json';$config=[IO.File]::ReadAllText($file)|ConvertFrom-Json;$profile=[IO.File]::ReadAllText((Join-Path $config.directory 'profile-result.json'))|ConvertFrom-Json
  if(-not $profile.complete -or -not $profile.ordinary -or -not $profile.dpapiRoundtrip -or $profile.userSid -ne $config.userSid -or @(Get-VM).Count){throw 'Independent ordinary profile and empty VM scope required'}
  $tools='C:\MuLab\upgrade-tools\'+$meta.caseId;if(Test-Path -LiteralPath $tools){throw 'Existing upgrade payload preserved'}
  if((Get-FileHash -LiteralPath $archive).Hash.ToLowerInvariant() -ne $meta.zipSha256){throw 'Transferred upgrade archive changed'}
  $support=[IO.File]::ReadAllText(('C:\MuLab\approved\image-'+$meta.supportCase+'-config.json'))|ConvertFrom-Json;$expected='C:\MuLab\image-tools\'+$meta.supportCase;$node=Join-Path $expected 'product/resources/node/node.exe'
  if($support.tools -ne $expected -or (Get-FileHash $support.image).Hash.ToLowerInvariant() -ne $meta.imageSha256 -or (Get-FileHash $node).Hash.ToLowerInvariant() -ne $meta.nodeSha256){throw 'Upgrade image or support runtime changed'}
  Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead($archive)
  try{[long]$size=0;if($zip.Entries.Count -gt 200){throw 'Upgrade payload file count exceeded'};foreach($entry in $zip.Entries){$name=$entry.FullName.Replace('\','/');$size+=$entry.Length;if($size -gt 1GB -or $entry.Length -gt 300MB -or $name.Contains(':') -or $name.StartsWith('/') -or @($name.Split('/')|Where-Object{$_ -in @('.','..')}).Count -or (-not $name.StartsWith('installers/') -and -not $name.StartsWith('brokers/') -and -not $name.StartsWith('node_modules/dns2/') -and $name -notin @('pro-upgrade-client.mjs','ProUpgradeStation.cs','local-fixtures.mjs','fixture-key.pem','fixture-cert.pem'))){throw 'Unsafe upgrade archive member'}}}finally{$zip.Dispose()}
  [IO.Compression.ZipFile]::ExtractToDirectory($archive,$tools);foreach($entry in $meta.files.psobject.Properties){if((Get-FileHash -LiteralPath (Join-Path $tools $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Upgrade staged file digest changed'}}
  $bin=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/bin';$pointer=Join-Path $bin 'current.json';$before=(Get-FileHash $pointer).Hash
  foreach($label in @('old','current')){$artifact=$meta.brokers.$label;foreach($entry in @(@{name=$artifact.brokerFile;hash=$artifact.brokerSha256;prefix='hv-broker-'},@{name=$artifact.channelFile;hash=$artifact.channelSha256;prefix='hv-channel-'})){
   if($entry.hash -notmatch '^[a-f0-9]{64}$' -or $entry.name -cne ($entry.prefix+$entry.hash.Substring(0,16)+'.exe')){throw 'Typed historical broker artifact required'};$source=Join-Path $tools ('brokers/'+$label+'/'+$entry.name);$target=Join-Path $bin $entry.name
   if((Get-FileHash $source).Hash.ToLowerInvariant() -ne $entry.hash){throw 'Historical broker changed'};if(Test-Path -LiteralPath $target){if((Get-FileHash $target).Hash.ToLowerInvariant() -ne $entry.hash){throw 'Existing protected broker differs'}}else{[IO.File]::Copy($source,$target,$false)}
   $acl=[Security.AccessControl.FileSecurity]::new();$acl.SetAccessRuleProtection($true,$false);$acl.SetOwner([Security.Principal.SecurityIdentifier]::new('S-1-5-32-544'));foreach($sid in @('S-1-5-18','S-1-5-32-544')){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new($sid),[Security.AccessControl.FileSystemRights]::FullControl,[Security.AccessControl.AccessControlType]::Allow))};$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new('S-1-5-32-545'),[Security.AccessControl.FileSystemRights]::ReadAndExecute,[Security.AccessControl.AccessControlType]::Allow));[IO.File]::SetAccessControl($target,$acl)
  }}
  if((Get-FileHash $pointer).Hash -ne $before){throw 'The existing default broker pointer changed'}
  foreach($pair in @(@('tools',$tools),@('brokers',$meta.brokers),@('versions',$meta.versions),@('supportCase',$meta.supportCase),@('node',$node),@('nodeSha256',$meta.nodeSha256),@('image',$support.image),@('imageSha256',$meta.imageSha256),@('clientSha256',$meta.files.'pro-upgrade-client.mjs'),@('stationSourceSha256',$meta.files.'ProUpgradeStation.cs'),@('defaultBrokerPointerSha256',$before.ToLowerInvariant()))){$config|Add-Member -NotePropertyName $pair[0] -NotePropertyValue $pair[1] -Force}
  $launcher='C:\MuLab\approved\upgrade-'+$meta.caseId+'-station-'+([string]$meta.files.'ProUpgradeStation.cs').Substring(0,16)+'.exe';if(Test-Path -LiteralPath $launcher){throw 'Existing versioned station launcher preserved'}
  Add-Type -TypeDefinition ([IO.File]::ReadAllText((Join-Path $tools 'ProUpgradeStation.cs'))) -ReferencedAssemblies @('System.dll','System.Core.dll','System.Web.Extensions.dll') -OutputAssembly $launcher -OutputType ConsoleApplication
  $config|Add-Member -NotePropertyName launcher -NotePropertyValue $launcher -Force;$config|Add-Member -NotePropertyName launcherSha256 -NotePropertyValue ((Get-FileHash $launcher).Hash.ToLowerInvariant()) -Force
  [IO.File]::WriteAllText($file,($config|ConvertTo-Json -Depth 16),[Text.UTF8Encoding]::new($false));return @{complete=$true;staged=$true;defaultBrokerPointerUnchanged=$true;originalInteractiveUser='MuLabUser';newUser=$config.userName}
 }
}
